{
  "environment_check": "usable_output",
  "reported_model": "transport_failed",
  "schema_version": "2.0",
  "status": "pre_fix_expected_failure"
}

from __future__ import annotations

import json
from pathlib import Path

from workflow.openmc_workflow import run_public_observation


TASK_DIR = Path(__file__).resolve().parent
REPORT_FILE = TASK_DIR / "outputs" / "public_reproduction_report.json"


def main() -> int:
    try:
        observation = run_public_observation()
    except Exception as exc:
        report = {
            "schema_version": "2.0",
            "status": "runner_failure",
            "error_type": type(exc).__name__,
            "error": str(exc),
        }
        exit_code = 2
    else:
        environment_status = observation["environment_check"]
        model_status = observation["reported_model"]
        if environment_status != "usable_output":
            status = "runner_failure"
            exit_code = 2
        elif model_status == "usable_output":
            status = "post_fix_success"
            exit_code = 0
        else:
            status = "pre_fix_expected_failure"
            exit_code = 1
        report = {
            "schema_version": "2.0",
            "status": status,
            "environment_check": environment_status,
            "reported_model": model_status,
        }

    REPORT_FILE.parent.mkdir(parents=True, exist_ok=True)
    REPORT_FILE.write_text(
        json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    print(json.dumps(report, indent=2, sort_keys=True))
    return exit_code


if __name__ == "__main__":
    raise SystemExit(main())

