   279	  // are identified consistently at small and large distance scales.
   280	  auto distance_coincident = [d](double d_axis) {
   281	    return coincident(d_axis, d) ||
   282	           (d != 0.0 && coincident(1.0, d_axis / d));
   283	  };
   284	
   285	  array<int, 3> lattice_trans = {0, 0, 0};
   286	  if (u.x != 0.0 && distance_coincident(d_x))
   287	    lattice_trans[0] = copysign(1, u.x);
   288	  if (u.y != 0.0 && distance_coincident(d_y))
   289	    lattice_trans[1] = copysign(1, u.y);
   290	  if (is_3d_ && u.z != 0.0 && distance_coincident(d_z))
   291	    lattice_trans[2] = copysign(1, u.z);
   292	
   293	  return {d, lattice_trans};
   294	}
